from common import *
B='021再来一次.txt'
make('meng_boshi','蒙博士',B,
'蒙博士是追求恢复青春的研究者，初登场时穿着晚礼服，从老人对衰老的感叹中寻找实验对象。他保存自愿录音和签署文件，试图以此说服卫斯理、小郭不要干预，却把实验地址、失败结果和参与者去向严格藏起；助手强行带走调查者的行为也使他不能只凭研究理想摆脱责任。所谓防衰老素没有按预想只令老人年轻若干年，而让身体回到巨大化的生命初始状态，随后长成与原貌迥异的形体。他承认早期结果失败，却又把新的形态和迅速增长的智力解释成意义重大的发现。其论证夹杂自信、时代先驱情结和未经验证的进化假说，不宜当作现实医学。卫斯理再次在夏威夷找到他时，他已为躲避暴露而消瘦，仍坚持这些生命是人，反驳只因外形不同就排斥他们的态度。最终他停止继续招募老人，决定与五名助手用余生教育照顾十九名实验者，并计划迁往洪都拉斯丛林。搬迁实际发生，但具体去向和后续成效无人证实。他的终局逻辑是承担已造成生命的责任，既不是无代价返老还童的神医，也不能因愿意照护而抹掉先前隐瞒风险的行为。',
'停止老人试验，带五名助手及十九名再生者迁离夏威夷，后续下落未知。','生命返始实验与再生者教育','使用小说内的防衰老素注射及实验室设备，使老人身体返始后重新发育；能学习不同发音系统并教育实验者。','无法保证现代人外形、控制遗传影响或恢复原人格；需药物、设备及长期照护。去丛林繁殖是计划，没有成功族群扩张实证。',[(290,318,'同意文件与隐瞒'),(810,820,'注射及意外返始'),(1460,1476,'智力增长、文字与互相恐惧'),(1601,1642,'停止新试验与照护计划'),(1662,1684,'搬离后失踪')],
'保住研究价值，并对自己改变的生命承担持续照护。',[('别人只因外貌要求消灭再生者','对方未看其沟通能力','用文字、学习表现争取承认其人格。'),('有人索求恢复青春','原技术仍会造成不可控返始','按终局决定拒绝新试验，解释此前失败。'),('研究所在地将暴露','居民恐慌且实验者无防护','优先转移和照护人员，同时谈判避免冲突。')],roles=('单书主角','阶段性对立者'),aliases=('蒙教授','杰教授'),scores=(1,1,2,3,2,2),tier='强',limits=(3,3,1),uncertainties=('同意程序不能证明受试者已充分知晓所有未预期风险。','再生者是否保留旧有记忆没有足够证据，不能自动人格合并。'))
make('meng_two_students','蒙博士的两名接引学生',B,
'这两名未具姓名的年轻男子戴眼镜，外表像大学生，是蒙博士保密研究与外界之间的执行者。他们参与把小郭带往秘密住所，又在其失踪地点等待预计会来查探的卫斯理。他们用装在金属管中的雪茄顶住卫斯理的腰，让对方误以为受到手枪威胁，随后主动揭开戏法，承认自己没有与卫斯理正面搏斗的把握。真正的筹码是对好奇心的判断：卫斯理若不肯蒙眼，就不再带他去见人。他们把身体强制、话术和控制信息混合使用，不能因语气礼貌而当成完全无害的引路人。另一方面，正文也没有赋予他们读心、枪械或超人身手；他们把小郭追踪仪移走的组织行动，与全知预判不同。后来卫斯理假装已经和博士谈妥，要求备车，他们在疑惑中照办，说明对博士权威的依赖可以被利用。在夏威夷，两名学生救醒受惊的邻居，并把她们所见解释成眼花，继续维护实验的秘密。五名助手终局都愿跟博士迁离，但不能确认其中每人的独立经历。本卡只保留两位接引执行者共同且可核实的行为，不把全体助手或博士技术叠加给二人。',
'两名接引者在后段仍参与保密；与全体助手一起迁离的具体个人去向未单列。','协同接引与信息封锁','以搭档配合、蒙眼路线、诱导和有限强制控制访客；利用对方好奇心促成会面。','雪茄管不是枪；自承正面不敌卫斯理。博士研究成果不算二人个人能力，两人必须实际在场才能协同。',[(179,235,'埋伏、假枪与心理诱导'),(325,351,'追踪装置被移走'),(990,1008,'受佯称指令骗过'),(1372,1385,'救醒邻居并否认所见')],
'维护导师的研究秘密，把外来接触限定在可控制范围。',[('调查者接近秘密地点','能借好奇心谈判','先提出可接受的会面条件，再选择是否带路。'),('访客声称得到导师许可','没有即时核验','倾向按熟悉权威行动，但可通过复核避免重蹈备车错误。'),('旁观者受到实验者惊吓','现场暴露风险上升','先帮助恢复，再试图控制信息传播。')],roles=('阶段性对立者','明确身份群体'),scores=(2,0,1,2,1,2),tier='并')
make('first_regrown_person','第一位可交流的再生者',B,
'这位没有留下原名的再生者是蒙博士向卫斯理展示的第一名实验对象，外形仍隐约像人，却有皱褶皮肤、难以辨识的五官和与通常人声不同的声音。他最初伏在床下，爬出后引发观看者极端恐惧；这段场景首先反映卫斯理的反应，不能据此认定实验者主动恐吓或怀有敌意。半年后，蒙博士报告他的智力已发展到成年人程度，能够使用文字，并形成适合自身发音器官的语言。他走到住处外的灌木附近时遇见两名推婴儿车的妇人，双方都被对方的形态吓坏；妇人晕倒，而他也几乎无力跑回。这个对称的恐惧使他成为本书关于何谓人的关键主体，而不只是实验失败的展品。他的思考和表达需要通过新身体学习，没有证据证明他保留某位老人的完整性格、学识和记忆，因此不能擅自将他认作郭老先生。最后他与其他再生者随研究群体消失，博士希望继续教育并建立可生存环境，实际发展仍未知。演绎中可让他以书写、距离和熟悉节奏争取理解，但这些是既有沟通能力的展开，不是额外心灵感应。',
'成长到可写字、具成人智力，随蒙博士群体迁离，后续未知。','新身体适应与文字沟通','重新发育后快速学习，能够书写并以自身声道发声；与常人的声音系统不兼容。','没有可确认的攻击性超能；不能用外貌推定强度或精神恐怖。旧人格连续性未明，语言需翻译或学习。',[(724,746,'首次出现的形体与行为'),(1341,1378,'与两名妇人相遇'),(1460,1476,'学习、书写及自身恐惧'),(1683,1684,'群体下落未知')],
'理解陌生身体与外界，争取能够安全交流的生活。',[('陌生人因外形尖叫','双方都在恐慌','退开并寻找熟悉的照护者，避免逼近。'),('能取得书写工具','对方愿意停下来阅读','优先写出需求，逐渐建立共同词汇。'),('被当作无意识实验物','有足够安全距离','展示已学会的判断和选择，要求把本人意愿纳入安排。')],scores=(1,0,1,2,1,1),tier='并',appearance='皱褶的红色皮肤，面部结构与常人不同；初次出现近似蜷伏的人形。',durability='改变后的活体，具体抗性未知，不推定免疫常规伤害。',speed='能爬行、移动和逃回住所，没有超高速证据。',intelligence={'in_combat':'遇陌生形体会恐惧，未显示战斗训练。','knowledge':'后段已能书写，蒙博士称其智力达成年人程度。','planning':'依靠安全环境与教育建立新生活。','adaptation':'快速学习，但新身体与人类社会交流仍有障碍。'},uncertainties=('无法与十九名老人中的某个原姓名可靠对应。',))
make('guo_elder_regrown','郭老先生',B,
'郭老先生是殷商郭奎的父亲，与老伴都是早期留学生，年逾八十仍愿意一同欣赏艺术演出。歌剧院散场时，他们因步履缓慢主动给年轻人让路，又轻声感叹青春流逝，这使他成为蒙博士恢复青春承诺的目标。他随后留下自愿参加实验的录音和手书，与妻子一起离开通常生活，家属则因失联而寻找。自愿的形式确有原文支持，但不能由此推定他已经知道实验会把身体改造成何种状态。卫斯理后来在实验室看到一个约六尺长、一端粗一端细、只能缓慢鼓动的生命体，蒙博士明确说那就是郭老先生，并把其状态解释为生命重新开始的阶段。此时的他没有亲自说出想法，也没有显示仍保留过去的学识、语言和夫妻关系记忆。人物卡因此必须把老年阶段可确认的人格、希望和决定，与再生阶段受制于设备的身体分开；不能让一个依赖氧气箱的生命体同时拥有无条件行动与原来完整知识。终局只知再生群体随博士消失，没有他恢复人形的证据。参战若需要可对话的人格，应明确恢复最后有自主表达的老人形态，并保留实验结局作为经历，而非宣称原作治疗成功。',
'实验后回到大型胚胎样生命状态，需氧气箱照护；后续个体情况未交代。','教育经历与自愿决策','老人阶段具艺术欣赏与受教育背景；参加实验的决定留下录音和签字。','再生状态未显示自主交流或战斗能力；没有成功返老还童的证明。恢复老人行动形态只属参战改编。',[(17,45,'夫妻的衰老感与接受邀请'),(59,68,'身份背景和失踪'),(290,299,'自愿记录'),(754,797,'氧气箱形体及博士说明')],
'希望重新获得生活机会，同时保留对自身身体变化的知情与选择。',[('别人提供恢复青春方案','风险尚未说明','追问可验证的后果，不只接受许诺。'),('被催促放弃剩余生命','对方以年老为理由轻视','坚持自己的余生仍需本人决定。'),('见到与同伴共同生活的机会','条件安全且可自主交流','先建立互助与日常节奏，再考虑更大改变。')],scores=(0,0,0,1,0,0),tier='纸',dead=True,aliases=('郭奎之父',),uncertainties=('未确认最后身体发展到何种成熟形态。',))
cov(B,[('白素','weisili_bai_su','跨书重要配角','识别失踪老人并提供车辆线索。'),('小郭','weisili_xiao_guo','跨书重要配角','诱查、被控制及追踪实验地点。'),('杰克','weisili_jieke','跨书重要配角','负责老人失踪案的警官。'),('蒙博士','meng_boshi','单书主角及阶段对立者','试验、隐藏后果、承担照护。'),('两名接引学生','meng_two_students','阶段性对立者','控制调查者与封锁地址。'),('第一位可交流再生者','first_regrown_person','单书主线人物','相遇和学习体现新生命主体。'),('郭老先生','guo_elder_regrown','单书主线人物','有姓名关系锚点、决定及个体实验结果。')],[('郭老太太及其余十八名再生者','参与实验属实，但除已单列者之外缺乏稳定个体对应、独立主线行为与终局人格信息，不杜撰逐人卡。'),('布朗、布朗太太、占太太、占先生','夏威夷线索提供及家庭经营人物，没有明确独立主角或反派线；布朗口头驱逐未落实为战斗。'),('郭奎、未名女助手和其余助手','家属信息或团队后勤；缺少独立主线，迁离选择并入博士证据。')],['原作涉及进化、衰老和历史人物的议论属于小说内解释，不转写成科学或历史定论。'])
